package br.com.sussmartcare.patientregistry.domain; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="patient_identifiers", uniqueConstraints=@UniqueConstraint(columnNames={"type","value"})) public class PatientIdentifier { @Id private UUID id; @Column(nullable=false) private UUID patientId; @Enumerated(EnumType.STRING) @Column(nullable=false) private IdentifierType type; @Column(nullable=false) private String value; protected PatientIdentifier(){} public PatientIdentifier(UUID patientId,IdentifierType type,String value){id=UUID.randomUUID();this.patientId=patientId;this.type=type;this.value=value;} public UUID getId(){return id;} public UUID getPatientId(){return patientId;} public IdentifierType getType(){return type;} public String getValue(){return value;} }
